SELECT * FROM artifacts JOIN artifact_authorlists ON artifact_authorlists.al_artifactid = artifacts.a_id WHERE func_jsort(artifact_authorlists.al_authorlist) LIKE '%sara%' AND func_jsortvalues(artifact_authorlists.al_authorlist) LIKE '%wang%' AND func_stem(artifacts.a_title) LIKE '%genom%' AND func_filterstopwords(artifacts.a_title) LIKE '%data%' AND func_keywords(artifacts.a_journal) LIKE '%phys%' AND func_stem(artifacts.a_journal) LIKE '%comput%' AND func_stem(artifacts.a_publisher) LIKE '%spring%' AND func_keywords(artifacts.a_publisher) LIKE '%press%' AND artifacts.a_year BETWEEN 2009 AND 2011;
SELECT * FROM artifacts JOIN views_stats ON views_stats.vs_artifactid = artifacts.a_id WHERE func_removeshortterms(artifacts.a_title) LIKE '%growth%' AND func_filterstopwords(artifacts.a_title) LIKE '%express%' AND func_keywords(artifacts.a_title) LIKE '%network%' AND func_stem(artifacts.a_title) LIKE '%quantum%' AND func_removeshortterms(artifacts.a_journal) LIKE '%learn%' AND func_filterstopwords(artifacts.a_journal) LIKE '%rev%' AND func_stem(artifacts.a_publisher) LIKE '%else%' AND func_keywords(artifacts.a_publisher) LIKE '%univ%' AND func_filterstopwords(artifacts.a_publisher) LIKE '%trans%' AND func_stem(artifacts.a_journal) LIKE '%nature%' AND views_stats.vs_count > 3 AND artifacts.a_year BETWEEN 2007 AND 2009;
SELECT * FROM artifacts JOIN artifact_authorlists ON artifact_authorlists.al_artifactid = artifacts.a_id WHERE func_jsort(artifact_authorlists.al_authorlist) LIKE '%wolf%' AND func_jsortvalues(artifact_authorlists.al_authorlist) LIKE '%zhang%' AND func_removeshortterms(artifacts.a_title) LIKE '%pattern%' AND func_filterstopwords(artifacts.a_title) LIKE '%power%' AND func_keywords(artifacts.a_title) LIKE '%state%' AND func_stem(artifacts.a_journal) LIKE '%bio%' AND func_keywords(artifacts.a_journal) LIKE '%control%' AND func_filterstopwords(artifacts.a_journal) LIKE '%eng%' AND func_stem(artifacts.a_publisher) LIKE '%wiley%' AND func_stem(artifacts.a_title) LIKE '%protein%' AND artifacts.a_year BETWEEN 2013 AND 2015;
